import{z as n,x as i,o,c as l,q as c,j as t,D as a,d as s,s as r,S as E}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"套接字 API","description":"","frontmatter":{"title":"套接字 API","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/socket-api.md","filePath":"cs/socket-api.md","lastUpdated":1791413859000}'),A={name:"cs/socket-api.md"};function p(B,e,_,h,D,P){const d=i("Mermaid");return o(),l("div",null,[e[2]||(e[2]=c('<h1 id="套接字-api" tabindex="-1">套接字 API <a class="header-anchor" href="#套接字-api" aria-label="Permalink to &quot;套接字 API&quot;">​</a></h1><div class="epigraph"><p>套接字是进程眼里的通信端点：像文件描述符一样 read/write，底下却是 UDP、TCP 或本地字节。</p><footer>—— 据 Leffler 等 BSD；Stevens, UNIX Network Programming 整理</footer></div><p><a href="/cs/anycast-edge">上一课</a>把对象放到边上，应用仍要写代码收发。<a href="/cs/process-image">进程</a>、<a href="/cs/file-bytestream">文件字节流</a>、<a href="/cs/syscall-path">系统调用</a>已齐；<a href="/cs/udp">UDP</a> 与 <a href="/cs/tcp-handshake">TCP 握手</a>已齐。缺口是把它们接起来的 <strong>Berkeley 套接字</strong>：内核对象 + 描述符。本课不进入关系模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每个协议一套系统调用，用户程序无法 <code>select</code> 等待磁盘与网卡。套接字把传输端点放进描述符表：<code>socket</code> 分配，<code>bind</code> 钉本地地址端口，<code>listen</code>/<code>accept</code> 接 TCP，<code>connect</code> 做握手，<code>send</code>/<code>recv</code> 搬字节。缺口不是再讲 LPM，而是这条用户接口。Unix 域套接字用同一套调用走<a href="/cs/ipc-pipe">管道</a>式本机路径。</p><p><span class="marginnote">直觉类比：描述符就是内核发的取餐牌——进程拿着号牌调 <code>read</code>/<code>write</code>，真正干活的后厨（TCP 控制块、缓冲区）全在内核里。套接字 API 的全部魔法，是让网络端点也挂上同一种号牌，于是磁盘、管道、网卡能用同一套机制统一等待。</span></p><p>本课不把 <code>epoll</code> 的全部边缘触发写完。</p><p><span class="marginnote">TCP 套接字是流，无消息边界；UDP 是数据报，<code>recv</code> 一次一报。类型在 <code>socket()</code> 的 <code>SOCK_STREAM</code> / <code>SOCK_DGRAM</code> 选定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>服务器：<code>socket</code> → <code>bind</code> → <code>listen</code> → 循环 <code>accept</code> 得新描述符 → fork 或线程处理。客户端：<code>socket</code> → <code>connect</code>。DNS 通常在 <code>getaddrinfo</code> 里先于 <code>connect</code>。阻塞调用沿用 OS 睡眠；就绪则下半部唤醒。错误经返回值，不像 mmap 缺页信号。</p><p><span class="marginnote">数字实例：<code>listen(fd, 128)</code> 里的 128 是 backlog——已完成握手、还没被 <code>accept</code> 领走的连接最多排 128 个。突发流量一旦超过它，新连接通常被拒或被丢；所以高并发服务都要配 accept 循环或线程池，尽快把排队连接收走。</span></p>',11)),(o(),t(E,null,{default:a(()=>[r(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FD%5B%22%E6%8F%8F%E8%BF%B0%E7%AC%A6%E8%A1%A8%22%5D%20--%3E%20SK%5B%22%E5%A5%97%E6%8E%A5%E5%AD%97%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20SK%20--%3E%20UDP%5B%22UDP%20%E7%AB%AF%E5%8F%A3%22%5D%0A%20%20SK%20--%3E%20TCP%5B%22TCP%20%E6%8E%A7%E5%88%B6%E5%9D%97%22%5D%0A%20%20SK%20--%3E%20UNIX%5B%22%E6%9C%AC%E5%9C%B0%E5%9F%9F%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=c('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>套接字是网络课收束到 OS 课的钉子：协议栈在内核（或用户库 + UDP），进程只看见描述符与字节。与 <a href="/cs/vfs">VFS</a> 并列：有的内核把套接字当一种文件操作表。CDN、HTTP、TLS 库都在这上面叠用户态逻辑；<a href="/cs/tls-handshake">TLS 握手</a>改变的是写入描述符之前是否加密，不是描述符本身。</p><p>地址族 <code>AF_INET</code>/<code>AF_INET6</code> 接 <a href="/cs/ipv6-contrast">IPv6 对照</a>。关闭描述符可触发 TCP 拆除，本课不画 TIME_WAIT。</p>',3)),(o(),t(E,null,{default:a(()=>[r(d,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%3A%20socket%20%E5%BB%BA%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%20--%3E%20S2%5B%22bind%20%E9%92%89%E4%BD%8F%E6%9C%AC%E5%9C%B0%E7%AB%AF%E5%8F%A3%22%5D%0A%20%20S2%20--%3E%20S3%5B%22listen%20%E6%8E%92%E9%98%9F%E7%AD%89%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20S3%20--%3E%20S4%5B%22accept%20%E5%8F%96%E5%87%BA%E5%B7%B2%E6%8F%A1%E6%89%8B%E8%BF%9E%E6%8E%A5%20%E8%BF%94%E5%9B%9E%E6%96%B0%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%0A%20%20C1%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%3A%20socket%22%5D%20--%3E%20C2%5B%22connect%20%E5%8F%91%E8%B5%B7%E4%B8%89%E6%AC%A1%E6%8F%A1%E6%89%8B%22%5D%0A%20%20C2%20--%3E%20S4%0A%20%20S4%20--%3E%20IO%5B%22%E5%8F%8C%E6%96%B9%20send%2Frecv%20%E6%90%AC%E5%AD%97%E8%8A%82%22%5D%0A%20%20IO%20--%3E%20CL%5B%22close%20%E8%A7%A6%E5%8F%91%E6%8B%86%E9%99%A4%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=c('<p><span class="marginnote">常见误区：以为 <code>accept</code> 返回的就是那个监听描述符。实际上每来一个新连接都得到一个<strong>新</strong>描述符，监听描述符原地不动继续接下一批——前者管通信、后者管接客，写成同一个变量会把自己堵死。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入原始套接字抓包的全部权限模型。不把 Windows IOCP 当另一理论。数据库后课从关系模型另起：套接字可以运 SQL 字节，但不定义表。</p><p><code>SO_REUSEADDR</code> 与绑定冲突、<code>TCP_NODELAY</code> 关 Nagle，都是套接字选项，不改协议状态机本身。本课默认阻塞 I/O。</p><p>后课默认：应用经套接字使用本栏已讲的传输与网络。阻塞与非阻塞下一课；数据库课程在后课，关系模型从「字节流里的表」另起抽象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>套接字 = 可 <code>read</code>/<code>write</code> 的传输端点，挂在进程描述符表上。</li><li>TCP 流、UDP 报、本地域共用调用形状。</li><li>阻塞与非阻塞下一课收束网络课；握手密码学在安全课，数据模型在数据库课。</li><li>出处：Stevens, <em>UNIX Network Programming</em>；BSD 套接字接口；Silberschatz et al. 网络子系统。</li></ul>',7))])}const T=n(A,[["render",p]]);export{m as __pageData,T as default};
